import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();
        if (n == 0) {
            System.out.println("Maximum loot possible : 0");
            return;
        }
        if (n == 1) {
            System.out.println("Maximum loot possible : " + nums[0]);
            return;
        }
        int prev2 = 0;
        int prev1 = nums[0];
        for (int i = 1; i < n; i++) {
            int take = nums[i] + prev2;
            int notTake = prev1;
            int curr = Math.max(take, notTake);
            prev2 = prev1;
            prev1 = curr;
        }
        System.out.println("Maximum loot possible : " + prev1);
    }
}
